const questions = [
  {
    id: 1,
    question: "Which of the following are compiled languages?",
    helpText: "Compiled languages are converted into machine code before the program is run, unlike interpreted languages.",
    options: ["C++", "Go", "Python", "Rust"],
  },
  {
    id: 2,
    question: "Which languages are primarily used for mobile app development?",
    options: ["Swift", "Kotlin", "SQL", "Dart"],
  },
  {
    id: 3,
    question: "Which of the following are considered low-level or system programming languages?",
    options: ["C", "Rust", "Assembly", "PHP"],
  },
];

const CheckboxGroup = ({ question, helpText, options, value, onChange }) => {
  return (
    <div className="form-field">
      <h2 className="text-xl font-bold text-gray-800 mb-2">{question}</h2>
      {helpText && <p className="help-text">{helpText}</p>}
      <div className="space-y-2">
        {options.map((option) => (
          <label key={option} className="checkbox-container">
            <input
              type="checkbox"
              className="checkbox-input"
              checked={value.includes(option)}
              onChange={(e) => {
                if (e.target.checked) {
                  onChange([...value, option]);
                } else {
                  onChange(value.filter((v) => v !== option));
                }
              }}
            />
            <span className="checkbox-label">{option}</span>
          </label>
        ))}
      </div>
    </div>
  );
};

const QuizApp = () => {
  const [answers, setAnswers] = useState({
    1: [],
    2: [],
    3: [],
  });
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
    console.log("Submitted Answers:", answers);
  };

  if (submitted) {
    return (
      <div className="bg-white p-10 rounded-2xl shadow-xl text-center">
        <div className="text-6xl mb-4">🎉</div>
        <h1 className="mb-4">Quiz Submitted!</h1>
        <p className="text-gray-600 mb-8">Thank you for participating in the computer languages quiz.</p>
        <button 
          onClick={() => setSubmitted(false)}
          className="text-indigo-600 font-semibold hover:underline"
        >
          Take it again
        </button>
      </div>
    );
  }

  return (
    <div className="py-8">
      <h1>Computer Languages Quiz</h1>
      <form onSubmit={handleSubmit}>
        {questions.map((q) => (
          <CheckboxGroup
            key={q.id}
            question={q.question}
            helpText={q.helpText}
            options={q.options}
            value={answers[q.id]}
            onChange={(newVal) => setAnswers({ ...answers, [q.id]: newVal })}
          />
        ))}
        <button type="submit" className="submit-button">
          Submit Quiz
        </button>
      </form>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<QuizApp />);
